FROM (SELECT * FROM temp_view_3) F0_0),
temp_view_0 AS (
SELECT /*+ materialize */ F0_0."AGGR_0" AS "AGGR_0", F0_0."AGGR_1" AS "AGGR_1", F0_0."GROUP_0" AS "GROUP_0", F1_0.prov_part_p__partkey AS prov_part_p__partkey, F1_0.prov_supplier_s__suppkey AS prov_supplier_s__suppkey, F1_0.prov_lineitem_l__orderkey AS prov_lineitem_l__orderkey, F1_0.prov_lineitem_l__linenumber AS prov_lineitem_l__linenumber, F1_0.prov_orders_o__orderkey AS prov_orders_o__orderkey, F1_0.prov_customer_c__custkey AS prov_customer_c__custkey, F1_0.prov_nation_n__nationkey AS prov_nation_n__nationkey, F1_0."prov_nation_1_n__nationkey" AS "prov_nation_1_n__nationkey", F1_0.prov_region_r__regionkey AS prov_region_r__regionkey
FROM ((
SELECT sum((CASE  WHEN (F0_0.nation = 'BRAZIL') THEN F0_0.volume ELSE 0 END)) AS "AGGR_0", sum(F0_0.volume) AS "AGGR_1", F0_0.o_year AS "GROUP_0"
FROM (SELECT * FROM temp_view_1) F0_0
GROUP BY F0_0.o_year) F0_0 JOIN (
SELECT F0_0."AGG_GB_ARG2" AS "_P_SIDE_GROUP_0", F0_0.prov_part_p__partkey AS prov_part_p__partkey, F0_0.prov_supplier_s__suppkey AS prov_supplier_s__suppkey, F0_0.prov_lineitem_l__orderkey AS prov_lineitem_l__orderkey, F0_0.prov_lineitem_l__linenumber AS prov_lineitem_l__linenumber, F0_0.prov_orders_o__orderkey AS prov_orders_o__orderkey, F0_0.prov_customer_c__custkey AS prov_customer_c__custkey, F0_0.prov_nation_n__nationkey AS prov_nation_n__nationkey, F0_0."prov_nation_1_n__nationkey" AS "prov_nation_1_n__nationkey", F0_0.prov_region_r__regionkey AS prov_region_r__regionkey
FROM (SELECT * FROM temp_view_2) F0_0) F1_0 ON ((F0_0."GROUP_0" = F1_0."_P_SIDE_GROUP_0"))))
SELECT F0_0.prov_part_p__partkey AS prov_part_p__partkey, F0_0.prov_supplier_s__suppkey AS prov_supplier_s__suppkey, F0_0.prov_lineitem_l__orderkey AS prov_lineitem_l__orderkey, F0_0.prov_lineitem_l__linenumber AS prov_lineitem_l__linenumber, F0_0.prov_orders_o__orderkey AS prov_orders_o__orderkey, F0_0.prov_customer_c__custkey AS prov_customer_c__custkey, F0_0.prov_nation_n__nationkey AS prov_nation_n__nationkey, F0_0."prov_nation_1_n__nationkey" AS "prov_nation_1_n__nationkey", F0_0.prov_region_r__regionkey AS prov_region_r__regionkey
FROM (
SELECT F0_0."GROUP_0" AS o_year, (F0_0."AGGR_0" / F0_0."AGGR_1") AS mkt_share, F0_0.prov_part_p__partkey AS prov_part_p__partkey, F0_0.prov_supplier_s__suppkey AS prov_supplier_s__suppkey, F0_0.prov_lineitem_l__orderkey AS prov_lineitem_l__orderkey, F0_0.prov_lineitem_l__linenumber AS prov_lineitem_l__linenumber, F0_0.prov_orders_o__orderkey AS prov_orders_o__orderkey, F0_0.prov_customer_c__custkey AS prov_customer_c__custkey, F0_0.prov_nation_n__nationkey AS prov_nation_n__nationkey, F0_0."prov_nation_1_n__nationkey" AS "prov_nation_1_n__nationkey", F0_0.prov_region_r__regionkey AS prov_region_r__regionkey
FROM (SELECT * FROM temp_view_0) F0_0
ORDER BY o_year ASC NULLS LAST) F0_0;


